using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class AudioAnalysisOperations
{
    private static Settings Failure(string message)=>new() {["error"]=message};
    private static bool Cancelled(RefCounted? job)=>job!=null&&job.Call("is_cancelled").AsBool();
    private static void Progress(RefCounted? job,double amount,string text){job?.Call("update",amount,text);}
    public Settings analysis_file_signature(string path){using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Read);return file!=null?new Settings {["file_bytes"]=(long)file.GetLength(),["modified"]=(long)Godot.FileAccess.GetModifiedTime(path)}:new Settings();}
    public bool pcm_file_current(string path,Settings info,Godot.FileAccess? file,bool inspectHeader){if(file!=null&&(long)file.GetLength()!=info["file_bytes"].AsInt64())return false;var expected=new Settings {["file_bytes"]=info["file_bytes"].AsInt64(),["modified"]=info["modified"].AsInt64()};if(!analysis_file_signature(path).RecursiveEqual(expected))return false;if(!inspectHeader)return true;using var pcm=new AudioPcmFileOperations();return pcm.inspect(path).RecursiveEqual(info);}
    public Settings analyze_pcm_file(string path,Settings info,double thresholdDb,double minimumSilence,RefCounted? job,double start,double duration)
    {
        double sourceDuration=info["duration"].AsDouble();int rate=info["rate"].AsInt32();if(!double.IsFinite(sourceDuration)||sourceDuration<=0||sourceDuration>86400)return Failure("PCM dialogue sources must be nonempty and at most 24 hours long.");if(start>=sourceDuration||(duration>0&&start+duration>sourceDuration+.0001))return Failure("The selected source window extends beyond the recording.");double end=duration<0?sourceDuration:Math.Min(sourceDuration,start+duration);if(end-start>7200)return Failure("Analyze at most two source hours at once. Split or trim the clip to a smaller source window.");long first=(long)Math.Ceiling(start*rate),last=end==sourceDuration?info["frames"].AsInt64():Math.Min(info["frames"].AsInt64(),(long)Math.Floor(end*rate)),total=last-first;if(total<=0)return Failure("The selected source window contains no complete audio frames.");if(Math.Ceiling((double)total*100/rate)>720000)return Failure("The selected source window exceeds the dialogue-envelope bound.");using var file=Godot.FileAccess.Open(path,Godot.FileAccess.ModeFlags.Read);if(file==null)return Failure("Could not open the PCM source for analysis.");if(!pcm_file_current(path,info,file,true))return Failure("The PCM source changed before analysis. Analyze it again.");var energies=new List<float>();double peak=0,sumSquared=0,blockPower=0;long cursor=0,blockEnd=Math.Min(total,(long)Math.Round(rate/100.0,MidpointRounding.AwayFromZero));int blockFrames=0;ulong checkedAt=Time.GetTicksMsec();using var pcm=new AudioPcmFileOperations();while(cursor<total){if(Cancelled(job))return Failure("Cancelled.");if(Time.GetTicksMsec()-checkedAt>=1000){checkedAt=Time.GetTicksMsec();if(!pcm_file_current(path,info,file,false))return Failure("The PCM source changed during analysis. Analyze it again.");}int count=(int)Math.Min(AudioPcmFileOperations.MaxReadFrames,total-cursor);var samples=pcm.read_frames(file,info,first+cursor,count);if(samples.Length!=count)return Failure("The PCM source ended before its declared analysis window. No partial detections were kept.");foreach(var sample in samples){peak=Math.Max(peak,Math.Max(Math.Abs(sample.X),Math.Abs(sample.Y)));blockPower+=((double)sample.X*sample.X+(double)sample.Y*sample.Y)*.5;blockFrames++;cursor++;if(cursor==blockEnd){energies.Add((float)Math.Sqrt(blockPower/blockFrames));sumSquared+=blockPower;blockPower=0;blockFrames=0;blockEnd=Math.Min(total,(long)Math.Round((double)(energies.Count+1)*rate/100,MidpointRounding.AwayFromZero));}}Progress(job,(double)cursor/total*.8,"Analyzing selected PCM source window");}if(!pcm_file_current(path,info,file,true))return Failure("The PCM source changed during analysis. Analyze it again.");var result=finish_pcm_analysis(energies.ToArray(),first,total,rate,sourceDuration,peak,sumSquared,thresholdDb,minimumSilence,job);if(result.TryGetValue("error",out var error)&&error.AsString().Length>0)return result;if(Cancelled(job))return Failure("Cancelled.");if(!pcm_file_current(path,info,null,true))return Failure("The PCM source changed during analysis. Analyze it again.");result["source_signature"]=info.Duplicate();Progress(job,1,"PCM dialogue analysis ready for review");return result;
    }
    public Settings finish_pcm_analysis(float[] energies,long first,long total,int rate,double sourceDuration,double peak,double sumSquared,double thresholdDb,double minimumSilence,RefCounted? job)
    {
        var transients=new Godot.Collections.Array<double>();var silences=new Godot.Collections.Array<Settings>();double threshold=Mathf.DbToLinear(thresholdDb),previous=0,average=0;long silenceStart=-1;int lastAttack=-100;double analyzedStart=(double)first/rate,analyzedEnd=(double)(first+total)/rate,analyzedDuration=(double)total/rate;bool tempoLimited=analyzedDuration>60;var onset=tempoLimited?Array.Empty<float>():new float[energies.Length];
        for(int index=0;index<energies.Length;index++){if(index%1024==0&&job!=null){if(Cancelled(job))return Failure("Cancelled.");Progress(job,.8+(double)index/energies.Length*.15,"Finding quiet source intervals");}long local=(long)Math.Round((double)index*rate/100,MidpointRounding.AwayFromZero);double at=(double)(first+local)/rate,energy=energies[index];average=average*.92+energy*.08;double flux=Math.Max(0,energy-previous);if(!tempoLimited)onset[index]=(float)flux;if(energy>threshold*2&&flux>Math.Max(.012,average*.6)&&index-lastAttack>=7){if(transients.Count>=65536)return Failure("More than 65536 attacks were detected. Analyze a shorter source window.");transients.Add(at);lastAttack=index;}if(energy<threshold){if(silenceStart<0)silenceStart=local;}else if(silenceStart>=0){if((double)(local-silenceStart)/rate>=minimumSilence){if(silences.Count>=2048)return Failure("More than 2048 quiet regions were detected. Increase the minimum pause duration or analyze a shorter source window.");silences.Add(new Settings {["start"]=(double)(first+silenceStart)/rate,["end"]=at});}silenceStart=-1;}previous=energy;}
        if(silenceStart>=0&&(double)(total-silenceStart)/rate>=minimumSilence){if(silences.Count>=2048)return Failure("More than 2048 quiet regions were detected. Increase the minimum pause duration or analyze a shorter source window.");silences.Add(new Settings {["start"]=(double)(first+silenceStart)/rate,["end"]=analyzedEnd});}double best=0,second=0;int bestLag=0;if(!tempoLimited)for(int lag=33;lag<=100;lag++){if(Cancelled(job))return Failure("Cancelled.");double correlation=0;for(int index=lag;index<onset.Length;index++)correlation+=(double)onset[index]*onset[index-lag];if(correlation>best){second=best;best=correlation;bestLag=lag;}else if(correlation>second)second=correlation;}double confidence=Math.Clamp((best-second)/Math.Max(.000001,best)*8,0,1);return new Settings {["error"]="",["transients"]=transients,["silences"]=silences,["peak_db"]=Mathf.LinearToDb(Math.Max(.000001,peak)),["rms_db"]=Mathf.LinearToDb(Math.Max(.000001,Math.Sqrt(sumSquared/total))),["tempo"]=bestLag>0?6000.0/bestLag:0,["confidence"]=confidence,["duration"]=sourceDuration,["envelope"]=energies,["envelope_rate"]=100,["envelope_start"]=analyzedStart,["analyzed_start"]=analyzedStart,["analyzed_end"]=analyzedEnd,["analyzed_duration"]=analyzedDuration,["windowed"]=first>0||analyzedEnd<sourceDuration,["method"]="Selected-window native PCM streaming",["tempo_limited"]=tempoLimited,["tempo_duration"]=tempoLimited?0:analyzedDuration};
    }
}
